#include <vector>

double sum_row_major(const std::vector<double>& m, int rows, int cols) {
    double total = 0;
    for (int i = 0; i < rows; ++i)
        for (int j = 0; j < cols; ++j)
            total += m[i * cols + j];
    return total;
}

double sum_col_major(const std::vector<double>& m, int rows, int cols) {
    double total = 0;
    for (int j = 0; j < cols; ++j)
        for (int i = 0; i < rows; ++i)
            total += m[i * cols + j];
    return total;
}

