#include <algorithm>
#include <cmath>
#include <vector>

// A European call on a flat (n + 1) x (n + 1) lattice:
// node (i, j) lives at v[i * (n + 1) + j]
double flat_lattice_price(double s, double k, double r, double sigma, double t, int n) {
    double dt = t / n;
    double u = std::exp(sigma * std::sqrt(dt)), d = 1 / u;
    double growth = std::exp(r * dt);
    double q = (growth - d) / (u - d), disc = 1 / growth;
    int w = n + 1;
    std::vector<double> v(w * w);
    // 1. leaves: row n, j = 0 to n
    // 2. step back from row n - 1 to row 0
    return v[0];
}

widget.solution:
#include <algorithm>
#include <cmath>
#include <vector>

double flat_lattice_price(double s, double k, double r, double sigma, double t, int n) {
    double dt = t / n;
    double u = std::exp(sigma * std::sqrt(dt)), d = 1 / u;
    double growth = std::exp(r * dt);
    double q = (growth - d) / (u - d), disc = 1 / growth;
    int w = n + 1;
    std::vector<double> v(w * w);
    for (int j = 0; j <= n; ++j)
        v[n * w + j] = std::max(s * std::pow(u, j) * std::pow(d, n - j) - k, 0.0);
    for (int i = n - 1; i >= 0; --i)
        for (int j = 0; j <= i; ++j)
            v[i * w + j] = disc * (q * v[(i + 1) * w + j + 1] + (1 - q) * v[(i + 1) * w + j]);
    return v[0];
}
